import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    t = int(input_data[0])
    results = []

    for i in range(t):
        s = input_data[i + 1]
        n = len(s)

        if n % 2 != 0:
            results.append("NO")
        else:
            half = n // 2
            if s[:half] == s[half:]:
                results.append("YES")
            else:
                results.append("NO")

    for res in results:
        print(res)

if __name__ == "__main__":
    main()
